const item = $input.first().json;
const src = (item.body && typeof item.body === 'object') ? item.body : item;
const message = String(src.message || '').trim();
const customerId = String(src.customer_id || '').trim();
const errors = [];
if (!message) errors.push('message is required');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(customerId)) errors.push('customer_id must be the customer UUID from the customers table');
const toText = v => (v === undefined || v === null) ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const base = String(item.supabase_url || '').replace(/\/+$/, '');
return [{ json: {
  valid: errors.length === 0, errors,
  customer_id: customerId, message,
  intent: toText(src.intent), memory: toText(src.memory), context: toText(src.context),
  customer_url: base + '/rest/v1/customers?id=eq.' + customerId + '&select=id,external_id,name,stripe_customer_id,stripe_subscription_id&limit=1',
  supabase_url: base, llm_model: item.llm_model
} }];

const c = $input.first().json;
const ok = !!(c && c.id);
return [{ json: { found: ok, has_stripe: !!(ok && c.stripe_customer_id), customer: ok ? c : null } }];

return [{ json: { success: true,
  response: "I'm sorry, I could not find a verified billing account for you, so I cannot share billing information right now. / দুঃখিত, আপনার জন্য যাচাইকৃত কোনো বিলিং অ্যাকাউন্ট খুঁজে পাইনি, তাই এখন বিলিং তথ্য দিতে পারছি না।",
  confidence: 0.3, data: { reason: 'no_stripe_account', evidence: [] }, needs_human: false, error: null, agent: 'billing' } }];

const chk = $('Check Billing Account').first().json;
const sub = $('Fetch Subscription').first().json || {};
const meters = $('Fetch Meters').first().json || {};
const list = Array.isArray(meters.data) ? meters.data : [];
const meter = list.find(m => m.event_name === 'ai_request');
const it = (sub.items && sub.items.data && sub.items.data[0]) || {};
const ps = it.current_period_start || sub.current_period_start || null;
const pe = it.current_period_end || sub.current_period_end || null;
let url = null, start = null, end = null;
if (meter && ps && sub.customer === chk.customer.stripe_customer_id) {
  start = Math.floor(ps / 60) * 60;
  const now = Math.floor(Date.now() / 1000 / 60) * 60;
  end = Math.min(now, pe || now);
  if (end > start) url = 'https://api.stripe.com/v1/billing/meters/' + meter.id + '/event_summaries?customer=' + encodeURIComponent(chk.customer.stripe_customer_id) + '&start_time=' + start + '&end_time=' + end;
}
return [{ json: { usage_url: url, usage_start: start, usage_end: end, meter_id: meter ? meter.id : null } }];

const ctx = $('Normalize Input').first().json;
const chk = $('Check Billing Account').first().json;
const cust = chk.customer;
const sid = cust.stripe_customer_id;
const NA = 'NOT AVAILABLE';
const good = o => !!(o && typeof o === 'object' && !o.error && o.object);
const money = (v, c) => (typeof v === 'number') ? (v / 100).toFixed(2) + ' ' + String(c || '').toUpperCase() : NA;
const ts = t => t ? new Date(t * 1000).toISOString() : NA;
const sub = $('Fetch Subscription').first().json;
const usage = $('Fetch Usage Summary').first().json;
const prep = $('Prepare Usage Request').first().json;
const inv = $('Fetch Invoices').first().json;
const prev = $('Preview Upcoming Invoice').first().json;
const ev = { customer: cust.external_id };
if (good(sub) && sub.customer === sid) {
  const it = (sub.items && sub.items.data && sub.items.data[0]) || {};
  const price = it.price || {};
  ev.subscription = { status: sub.status, collection_method: sub.collection_method, plan: price.nickname || NA, unit_price_per_request: money(price.unit_amount, price.currency), billing_interval: price.recurring ? price.recurring.interval : NA, current_period_start: ts(it.current_period_start || sub.current_period_start), current_period_end: ts(it.current_period_end || sub.current_period_end), cancel_at_period_end: sub.cancel_at_period_end };
} else { ev.subscription = NA; }
if (good(usage) && usage.object === 'list' && Array.isArray(usage.data)) {
  const total = usage.data.reduce((s, r) => s + (Number(r.aggregated_value) || 0), 0);
  ev.usage = { requests_this_period: total, counted_from: ts(prep.usage_start), counted_until: ts(prep.usage_end) };
} else { ev.usage = NA; }
if (good(prev) && prev.object === 'invoice' && prev.customer === sid) {
  ev.upcoming_invoice_estimate = { total: money(prev.total, prev.currency), amount_due: money(prev.amount_due, prev.currency) };
} else { ev.upcoming_invoice_estimate = NA; }
if (good(inv) && inv.object === 'list' && Array.isArray(inv.data)) {
  ev.recent_invoices = inv.data.filter(i => i.customer === sid).map(i => ({ invoice_number: i.number || NA, status: i.status, total: money(i.total, i.currency), amount_due: money(i.amount_due, i.currency), created: ts(i.created), link: i.hosted_invoice_url || NA }));
} else { ev.recent_invoices = NA; }
const system = 'You are the Billing Agent of a small business. Use ONLY the BILLING DATA provided; it was read from Stripe for this customer only. Rules: (1) Never invent usage, amounts, invoice numbers, invoice status, subscription status, payment status or any billing fact. If a value is NOT AVAILABLE or missing, say you do not have that verified information. (2) Usage is counted in AI requests; unit price comes from the subscription data. Do not calculate anything other than what the data states; quote the numbers exactly as given. (3) You cannot change subscriptions, cancel plans, send or resend invoices, apply credits or refunds: no authorization rules are configured. For such a request say it will be recorded and passed to the team for review, and use request_type subscription_change or invoice_request. (4) If the customer asks for a human use request_type human_handoff. (5) CUSTOMER MEMORY is background only, never a source of billing facts. (6) Reply in the same language as the customer message. Return ONLY a JSON object: {"response": string, "confidence": number between 0 and 1, "request_type": one of usage_lookup, invoice_lookup, subscription_lookup, subscription_change, invoice_request, human_handoff, general, "summary": one short English sentence describing the customer issue, "needs_human": boolean (true for subscription_change, invoice_request and human_handoff), "handoff_reason": string or null}. confidence reflects how well BILLING DATA supports your answer.';
const user = 'BILLING DATA (this customer only):\n' + JSON.stringify(ev, null, 1) + '\n\nCUSTOMER MEMORY (background only):\n' + (ctx.memory || 'none') + '\n\nCUSTOMER MESSAGE:\n' + ctx.message + (ctx.context ? '\n\nSUPERVISOR REVIEW NOTE (a previous answer was rejected; answer again using ONLY the billing data above and remove any unsupported claim):\n' + ctx.context : '');
return [{ json: { customer_id: ctx.customer_id, message: ctx.message, supabase_url: ctx.supabase_url, llm_model: ctx.llm_model, evidence: [ev], system_prompt: system, user_prompt: user } }];

const b = $('Build Context').first().json;
const ai = $input.first().json;
let content = ai.choices[0].message.content;
content = String(content).replace(/```json|```/g, '').trim();
const p = JSON.parse(content);
const allowed = ['usage_lookup', 'invoice_lookup', 'subscription_lookup', 'subscription_change', 'invoice_request', 'human_handoff', 'general'];
const type = allowed.includes(p.request_type) ? p.request_type : 'general';
const response = String(p.response || '').trim();
if (!response) throw new Error('LLM returned an empty response');
const confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
const needsHuman = ['subscription_change', 'invoice_request', 'human_handoff'].includes(type);
const ticket = needsHuman ? { customer_id: b.customer_id, order_id: null, type, summary: String(p.summary || '').slice(0, 500), message: String(b.message).slice(0, 2000), status: type === 'human_handoff' ? 'open' : 'pending_human_review' } : null;
const dupUrl = needsHuman ? (b.supabase_url + '/rest/v1/support_tickets?customer_id=eq.' + b.customer_id + '&type=eq.' + type + '&order_id=is.null&status=in.(open,pending_human_review)&order=created_at.desc&limit=1&select=id,status') : null;
return [{ json: { dup_url: dupUrl, create_ticket: needsHuman, ticket_payload: ticket, response, confidence, request_type: type, needs_human: needsHuman, handoff_reason: needsHuman ? String(p.handoff_reason || type).slice(0, 300) : null, supabase_url: b.supabase_url } }];

const p = $('Parse & Decide').first().json;
let ticket = null, dup = false;
try { const t = $('Insert Ticket').first().json; if (t && t.id) ticket = t; } catch (e) {}
if (!ticket) { try { const t = $('Check Duplicate Ticket').first().json; if (t && t.id) { ticket = t; dup = true; } } catch (e) {} }
const ref = ticket ? String(ticket.id).slice(0, 8).toUpperCase() : null;
return [{ json: { success: true, response: p.response + (ref ? '\n\nReference: ' + ref + (dup ? ' (existing request, no new ticket was created)' : '') : ''), confidence: p.confidence,
  data: { request_type: p.request_type, ticket_id: ticket ? ticket.id : null, ticket_reference: ref, ticket_status: ticket ? ticket.status : null, ticket_duplicate: dup, handoff_reason: p.handoff_reason, evidence: $('Build Context').first().json.evidence },
  needs_human: p.needs_human, error: null, agent: 'billing' } }];

const j = $input.first().json || {};
const e = j.error || j;
const msg = String(e.message || e.description || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 500);
return [{ json: { success: false, response: null, confidence: 0, data: {}, needs_human: true, error: 'billing_agent_failed: ' + msg, agent: 'billing' } }];
